"""


def sub_help(tool: str) -> str:
    summaries = {
        "intersect": ("bedtools intersect (aka intersectBed)", "Report overlaps between two feature files.", "bedtools intersect [OPTIONS] -a <bed/gff/vcf/bam> -b <bed/gff/vcf/bam>"),
        "merge": ("bedtools merge (aka mergeBed)", "Merges overlapping BED/GFF/VCF entries into a single interval.", "bedtools merge [OPTIONS] -i <bed/gff/vcf>"),
        "genomecov": ("bedtools genomecov (aka genomeCoverageBed)", "Compute the coverage of a feature file among a genome.", "bedtools genomecov [OPTIONS] -i <bed/gff/vcf> -g <genome>"),
        "jaccard": ("bedtools jaccard (aka jaccard)", "Calculate Jaccard statistic b/w two feature files.", "bedtools jaccard [OPTIONS] -a <bed/gff/vcf> -b <bed/gff/vcf>"),
        "makewindows": ("bedtools makewindows", "Makes adjacent or sliding windows across a genome or BED file.", "bedtools makewindows [OPTIONS] [-g <genome> OR -b <bed>] [ -w <window_size> OR -n <number> ]"),
        "closest": ("bedtools closest (aka closestBed)", "Find the closest interval in B to each interval in A.", "bedtools closest [OPTIONS] -a <bed> -b <bed>"),
        "coverage": ("bedtools coverage (aka coverageBed)", "Compute coverage of B over A intervals.", "bedtools coverage [OPTIONS] -a <bed> -b <bed>"),
        "map": ("bedtools map", "Apply a function to B fields for each A interval.", "bedtools map [OPTIONS] -a <bed> -b <bed> -c <col> -o <op>"),
        "window": ("bedtools window (aka windowBed)", "Find B intervals in a window around A.", "bedtools window [OPTIONS] -a <bed> -b <bed>"),
        "subtract": ("bedtools subtract (aka subtractBed)", "Remove intervals based on overlaps b/w two files.", "bedtools subtract [OPTIONS] -a <bed> -b <bed>"),
        "slop": ("bedtools slop (aka slopBed)", "Adjust the size of intervals.", "bedtools slop [OPTIONS] -i <bed> -g <genome>"),
        "flank": ("bedtools flank (aka flankBed)", "Create flanking intervals.", "bedtools flank [OPTIONS] -i <bed> -g <genome>"),
        "sort": ("bedtools sort (aka sortBed)", "Order the intervals in a file.", "bedtools sort [OPTIONS] -i <bed>"),
        "groupby": ("bedtools groupby", "Group by common columns and summarize others.", "bedtools groupby [OPTIONS] -i <file> -g <cols> -c <cols> -o <ops>"),
    }
    title, summary, usage = summaries.get(tool, (f"bedtools {tool}", "", f"bedtools {tool} [OPTIONS]"))
    return f"\nTool:    {title}\nVersion: {VERSION}\nSummary: {summary}\n\nUsage:   {usage}\n\nOptions: \n\t-h\tPrint this help menu.\n\n"


# ---------------------------------------------------------------------------
# Parser helper


def parse_common_ab(args: List[str]) -> Dict[str, object]:
    opts: Dict[str, object] = {"a": None, "b": [], "flags": set()}
    i = 0
    while i < len(args):
        t = args[i]
        if t == "-a":
            opts["a"] = args[i + 1]
            i += 2
        elif t == "-b":
            i += 1
            bs = []
            while i < len(args) and not is_option_token(args[i]):
                bs.append(args[i])
                i += 1
            opts["b"] = bs
        else:
            i += 1
    return opts


# ---------------------------------------------------------------------------
# intersect


def cmd_intersect(args: List[str]) -> int:
    if "-h" in args or "--help" in args or not args:
        sys.stderr.write(sub_help("intersect"))
        return 1
    opts = {
        "a": None,
        "b": [],
        "wa": False,
        "wb": False,
        "wo": False,
        "wao": False,
        "loj": False,
        "u": False,
        "c": False,
        "C": False,
        "v": False,
        "s": False,
        "S": False,
        "f": 1e-9,
        "F": 1e-9,
        "r": False,
        "e": False,
        "split": False,
        "header": False,
        "names": [],
        "filenames": False,
        "sortout": False,
    }
    i = 0
    while i < len(args):
        t = args[i]
        if t == "-a":
            opts["a"] = args[i + 1]
            i += 2
        elif t == "-b":
            i += 1
            bs = []
            while i < len(args) and not is_option_token(args[i]):
                bs.append(args[i])
                i += 1
            opts["b"] = bs
        elif t in ("-wa", "-wb", "-wo", "-wao", "-loj", "-u", "-c", "-C", "-v", "-s", "-S", "-r", "-e", "-split", "-header", "-filenames", "-sortout"):
            key = t.lstrip("-")
            opts[key] = True
            i += 1
        elif t in ("-f", "-F"):
            opts[t.lstrip("-")] = float(args[i + 1])
            i += 2
        elif t == "-names":
            i += 1
            names = []
            while i < len(args) and not is_option_token(args[i]):
                names.append(args[i])
                i += 1
            opts["names"] = names
        elif t in ("-sorted", "-g", "-nonamecheck", "-bed", "-ubam", "-nobuf", "-iobuf"):
            # Accepted/ignored, consume argument for those that have one.
            if t in ("-g", "-iobuf") and i + 1 < len(args):
                i += 2
            else:
                i += 1
        else:
            i += 1
    if not opts["a"] or not opts["b"]:
        sys.stderr.write(sub_help("intersect"))
        return 1
    try:
        aheaders, arecs = read_records(str(opts["a"]))
        b_files = [str(x) for x in opts["b"]]
        b_headers_records = [read_records(p) for p in b_files]
    except Exception as exc:
        err(str(exc))
        return 1
    b_records_list = [br for _h, br in b_headers_records]
    b_indexes = [IntervalIndex(br) for br in b_records_list]
    if opts["header"]:
        for h in aheaders:
            sys.stdout.write(h + "\n")
    multi = len(b_files) > 1
    aliases: List[str] = list(opts["names"] or [])
    max_b_cols = max_field_count(b_records_list)

    def label(file_idx: int) -> str:
        if opts["filenames"]:
            return b_files[file_idx]
        if aliases and file_idx < len(aliases):
            return aliases[file_idx]
        return str(file_idx + 1)

    for a in arecs:
        per_file_hits: List[List[Tuple[int, Record, Tuple[int, int, int]]]] = []
        all_hits: List[Tuple[int, Record, Tuple[int, int, int]]] = []
        for fi, idx in enumerate(b_indexes):
            hits: List[Tuple[int, Record, Tuple[int, int, int]]] = []
            for b in idx.query(a.chrom, a.start, a.end):
                if not strand_ok(a, b, bool(opts["s"]), bool(opts["S"])):
                    continue
                pieces = overlap_pieces(a, b, float(opts["f"]), float(opts["F"]), bool(opts["r"]), bool(opts["e"]), bool(opts["split"]))
                for piece in pieces:
                    hits.append((fi, b, piece))
            if opts["sortout"]:
                hits.sort(key=lambda x: (x[1].chrom, x[1].start, x[1].end, x[1].order))
            per_file_hits.append(hits)
            all_hits.extend(hits)
        has_hit = bool(all_hits)
        if opts["C"]:
            for fi, hits in enumerate(per_file_hits):
                extra = [label(fi)] if multi or aliases or opts["filenames"] else []
                out_line(a.fields + extra + [str(len(hits))])
            continue
        if opts["c"]:
            out_line(a.fields + [str(len(all_hits))])
            continue
        if opts["u"]:
            if has_hit:
                out_line(a.fields)
            continue
        if opts["v"]:
            if not has_hit:
                out_line(a.fields)
            continue
        if not has_hit:
            if opts["wao"] or opts["loj"]:
                extra = ["."] if multi else []
                row = a.fields + extra + null_b_fields(max_b_cols)
                if opts["wao"]:
                    row += ["0"]
                out_line(row)
            continue
        for fi, b, piece in all_hits:
            s, e, ol = piece
            id_extra = [label(fi)] if multi and (opts["wb"] or opts["wo"] or opts["wao"] or opts["loj"]) else []
            if opts["wo"]:
                out_line(a.fields + id_extra + b.fields + [str(ol)])
            elif opts["wao"]:
                out_line(a.fields + id_extra + b.fields + [str(ol)])
            elif opts["loj"]:
                out_line(a.fields + id_extra + b.fields)
            elif opts["wa"] and opts["wb"]:
                out_line(a.fields + id_extra + b.fields)
            elif opts["wa"]:
                out_line(a.fields)
            elif opts["wb"]:
                out_line(a.fields_with_coords(s, e) + id_extra + b.fields)
            else:
                out_line(a.fields_with_coords(s, e))
    return 0


