def cmd_map(args: List[str]) -> int:
    if "-h" in args or "--help" in args:
        sys.stderr.write(sub_help("map")); return 1
    opts = {"a": None, "b": None, "c": [5], "o": ["sum"], "null": ".", "delim": ",", "s": False, "S": False, "f": 1e-9, "F": 1e-9, "r": False, "e": False, "split": False, "header": False}
    i = 0
    while i < len(args):
        t = args[i]
        if t == "-a": opts["a"] = args[i+1]; i += 2
        elif t == "-b": opts["b"] = args[i+1]; i += 2
        elif t == "-c": opts["c"] = parse_cols(args[i+1]); i += 2
        elif t == "-o": opts["o"] = parse_ops(args[i+1]); i += 2
        elif t == "-null": opts["null"] = args[i+1]; i += 2
        elif t == "-delim": opts["delim"] = args[i+1]; i += 2
        elif t in ("-s", "-S", "-r", "-e", "-split", "-header"):
            opts[t.lstrip("-")] = True; i += 1
        elif t in ("-f", "-F"):
            opts[t.lstrip("-")] = float(args[i+1]); i += 2
        else: i += 1
    if not opts["a"] or not opts["b"]:
        sys.stderr.write(sub_help("map")); return 1
    try:
        aheaders, arecs = read_records(str(opts["a"]))
        _h, brecs = read_records(str(opts["b"]))
    except Exception as exc:
        err(str(exc)); return 1
    if opts["header"]:
        for h in aheaders: sys.stdout.write(h + "\n")
    idx = IntervalIndex(brecs)
    pairs = expand_col_op_pairs(opts["c"], opts["o"])
    for a in arecs:
        hits: List[Record] = []
        for b in idx.query(a.chrom, a.start, a.end):
            if not strand_ok(a, b, opts["s"], opts["S"]):
                continue
            if overlap_pieces(a, b, opts["f"], opts["F"], opts["r"], opts["e"], opts["split"]):
                hits.append(b)
        row = list(a.fields)
        if not hits:
            row += [str(opts["null"])] * len(pairs)
        else:
            for col, op in pairs:
                vals = [b.fields[col-1] for b in hits if len(b.fields) >= col]
                row.append(aggregate_values(vals, op, str(opts["delim"])))
        out_line(row)
    return 0


def cmd_window(args: List[str]) -> int:
