        err(str(exc)); return 1
    if opts["header"]:
        for h in aheaders: sys.stdout.write(h + "\n")
    idx = IntervalIndex(brecs)
    for a in arecs:
        left = int(opts["l"]); right = int(opts["r"])
        if opts["sw"] and a.strand == "-":
            ws, we = a.start - right, a.end + left
        else:
            ws, we = a.start - left, a.end + right
        same, opp = bool(opts["sm"]), bool(opts["Sm"])
        hits = [b for b in idx.query(a.chrom, ws, we) if strand_ok(a, b, same, opp)]
        if opts["c"]:
            out_line(a.fields + [len(hits)])
        elif opts["u"]:
            if hits: out_line(a.fields)
        elif opts["v"]:
            if not hits: out_line(a.fields)
        else:
            for b in hits:
                out_line(a.fields + b.fields)
    return 0


def cmd_closest(args: List[str]) -> int:
    if "-h" in args or "--help" in args:
        sys.stderr.write(sub_help("closest")); return 1
    opts = {"a": None, "b": [], "d": False, "D": None, "io": False, "s": False, "S": False, "k": 1, "t": "all", "header": False, "names": [], "filenames": False, "iu": False, "id": False}
    i = 0
    while i < len(args):
        t = args[i]
        if t == "-a": opts["a"] = args[i+1]; i += 2
        elif t == "-b":
            i += 1; bs = []
            while i < len(args) and not is_option_token(args[i]): bs.append(args[i]); i += 1
            opts["b"] = bs
        elif t == "-d": opts["d"] = True; i += 1
        elif t == "-D": opts["D"] = args[i+1]; i += 2
        elif t == "-k": opts["k"] = int(args[i+1]); i += 2
        elif t == "-t": opts["t"] = args[i+1]; i += 2
        elif t == "-names":
            i += 1; names=[]
            while i < len(args) and not is_option_token(args[i]): names.append(args[i]); i += 1
            opts["names"] = names
        elif t in ("-io", "-s", "-S", "-header", "-filenames", "-iu", "-id"):
            opts[t.lstrip("-")] = True; i += 1
        else: i += 1
    if not opts["a"] or not opts["b"]:
        sys.stderr.write(sub_help("closest")); return 1
    try:
        aheaders, arecs = read_records(str(opts["a"]))
        b_files = [str(x) for x in opts["b"]]
        b_lists = [read_records(p)[1] for p in b_files]
    except Exception as exc:
        err(str(exc)); return 1
    if opts["header"]:
        for h in aheaders: sys.stdout.write(h + "\n")
    multi = len(b_lists) > 1
    maxcols = max_field_count(b_lists)
    aliases = list(opts["names"] or [])
    def label(fi):
        if opts["filenames"]: return b_files[fi]
        if aliases and fi < len(aliases): return aliases[fi]
        return str(fi+1)
    all_by_chrom: Dict[str, List[Tuple[int, Record]]] = collections.defaultdict(list)
    for fi, bl in enumerate(b_lists):
        for b in bl:
            all_by_chrom[b.chrom].append((fi, b))
    for chrom in list(all_by_chrom):
        all_by_chrom[chrom].sort(key=lambda x: (x[1].start, x[1].end, x[0], x[1].order))
    for a in arecs:
        candidates: List[Tuple[int, Record, int, int]] = []  # file, rec, absdist, signed/refdist
        overlaps: List[Tuple[int, Record, int, int]] = []
        for fi, b in all_by_chrom.get(a.chrom, []):
            if not strand_ok(a, b, opts["s"], opts["S"]):
                continue
            dist = distance_between(a, b)
            sd = signed_distance(a, b, str(opts["D"] or "ref"))
            if opts["iu"] and sd < 0: continue
            if opts["id"] and sd > 0: continue
            if dist == 0 and not opts["io"]:
                overlaps.append((fi, b, 0, 0))
            elif dist != 0:
                candidates.append((fi, b, dist, sd))
        chosen: List[Tuple[int, Record, int, int]]
        if overlaps:
            chosen = overlaps
        elif candidates:
            candidates.sort(key=lambda x: (x[2], x[0], x[1].order))
            k = max(1, int(opts["k"]))
            if opts["t"] == "first":
                chosen = [candidates[0]]
            elif opts["t"] == "last":
                mind = candidates[0][2]
                ties = [c for c in candidates if c[2] == mind]
                chosen = [ties[-1]]
            else:
                # Include all ties at the kth distance, matching bedtools' default tie behaviour.
                kth = candidates[min(k, len(candidates)) - 1][2]
                chosen = [c for c in candidates if c[2] <= kth]
        else:
            extra = ["."] if multi else []
            row = a.fields + extra + null_b_fields(maxcols)
            if opts["d"] or opts["D"]:
                row += ["-1"]
            out_line(row)
            continue
        for fi, b, dist, sd in chosen:
            extra = [label(fi)] if multi else []
            row = a.fields + extra + b.fields
            if opts["D"]:
                row.append(str(sd))
            elif opts["d"]:
                row.append(str(dist))
            out_line(row)
    return 0


def cmd_subtract(args: List[str]) -> int:
    if "-h" in args or "--help" in args:
        sys.stderr.write(sub_help("subtract")); return 1
    opts = {"a": None, "b": None, "A": False, "N": False, "s": False, "S": False, "f": 1e-9, "F": 1e-9, "r": False, "e": False, "split": False}
    i = 0
    while i < len(args):
        t = args[i]
        if t == "-a": opts["a"] = args[i+1]; i += 2
        elif t == "-b": opts["b"] = args[i+1]; i += 2
        elif t in ("-A", "-N", "-s", "-S", "-r", "-e", "-split"):
            opts[t.lstrip("-")] = True; i += 1
        elif t in ("-f", "-F"):
            opts[t.lstrip("-")] = float(args[i+1]); i += 2
        else: i += 1
    if not opts["a"] or not opts["b"]:
        sys.stderr.write(sub_help("subtract")); return 1
    try:
        _h, arecs = read_records(str(opts["a"]))
        _h, brecs = read_records(str(opts["b"]))
    except Exception as exc:
        err(str(exc)); return 1
    idx = IntervalIndex(brecs)
    for a in arecs:
        sub: List[Tuple[int, int]] = []
        total_olap = 0
        for b in idx.query(a.chrom, a.start, a.end):
            if not strand_ok(a, b, opts["s"], opts["S"]): continue
            pieces = overlap_pieces(a, b, opts["f"], opts["F"], opts["r"], opts["e"], opts["split"])
            for s, e, ol in pieces:
                s = max(s, a.start); e = min(e, a.end)
                if e > s:
                    sub.append((s, e)); total_olap += e - s
        if opts["A"] and sub:
            continue
        if opts["N"] and total_olap / max(1, a.length()) >= opts["f"]:
            continue
        if not sub:
            out_line(a.fields); continue
        sub.sort()
        cur = a.start
        for s, e in sub:
            if s > cur:
                out_line(a.fields_with_coords(cur, s))
            cur = max(cur, e)
        if cur < a.end:
            out_line(a.fields_with_coords(cur, a.end))
    return 0


