            for cc,ll in choices:
                acc2 += ll
                if y < acc2: c=cc; ln=ll; break
        maxstart=max(0,ln-length); s=rng.randint(0,maxstart) if maxstart else 0
        f=r.copy_fields(); f[0]=c; f[1]=str(s); f[2]=str(s+length); out_line(f)
    return 0


def cmd_sample(args: List[str]) -> int:
    ipath=None; n=None; frac=None; seed=None
    i=0
    while i<len(args):
        if args[i]=="-i": ipath=args[i+1]; i+=2
        elif args[i]=="-n": n=int(args[i+1]); i+=2
        elif args[i]=="-f": frac=float(args[i+1]); i+=2
        elif args[i]=="-seed": seed=int(args[i+1]); i+=2
        elif args[i] in ("-h","--help"):
            sys.stderr.write(sub_help("sample")); return 1
        else: i+=1
    if not ipath: return 1
    _h,recs=read_records(ipath); rng=pyrandom.Random(seed)
    if frac is not None: chosen=[r for r in recs if rng.random()<frac]
    else: chosen=rng.sample(recs, min(n if n is not None else 1, len(recs)))
    chosen.sort(key=lambda r:r.order)
    for r in chosen: out_line(r.fields)
    return 0


def cmd_overlap(args: List[str]) -> int:
    # Legacy utility: overlap <a_start> <a_end> <b_start> <b_end> or BED lines on stdin.
    nums=[int(x) for x in args if is_int(x)]
    if len(nums)>=4:
        print(overlap_len_coords(nums[0],nums[1],nums[2],nums[3])); return 0
    for line in sys.stdin:
        f=split_fields(line)
        if len(f)>=6 and all(is_int(x) for x in (f[1],f[2],f[4],f[5])):
            out_line(f+[overlap_len_coords(int(f[1]),int(f[2]),int(f[4]),int(f[5]))])
    return 0


# ---------------------------------------------------------------------------
# Main dispatch


ALIASES = {
    "intersectbed": "intersect",
    "windowbed": "window",
    "closestbed": "closest",
    "coveragebed": "coverage",
    "mapbed": "map",
    "genomecoveragebed": "genomecov",
    "genomecovbed": "genomecov",
    "mergebed": "merge",
    "clusterbed": "cluster",
    "complementbed": "complement",
    "shiftbed": "shift",
    "subtractbed": "subtract",
    "slopbed": "slop",
    "flankbed": "flank",
    "sortbed": "sort",
    "bed12tobed6": "bed12tobed6",
    "bedtobed6": "bed12tobed6",
}

COMMANDS = {
    "intersect": cmd_intersect,
    "merge": cmd_merge,
    "complement": cmd_complement,
    "genomecov": cmd_genomecov,
    "jaccard": cmd_jaccard,
    "makewindows": cmd_makewindows,
    "closest": cmd_closest,
    "subtract": cmd_subtract,
    "flank": cmd_flank,
    "slop": cmd_slop,
    "coverage": cmd_coverage,
    "map": cmd_map,
    "window": cmd_window,
    "sort": cmd_sort,
    "groupby": cmd_groupby,
    "cluster": cmd_cluster,
    "spacing": cmd_spacing,
    "shift": cmd_shift,
    "random": cmd_random,
    "shuffle": cmd_shuffle,
    "sample": cmd_sample,
    "bed12tobed6": cmd_bed12tobed6,
    "overlap": cmd_overlap,
}


def main(argv: List[str]) -> int:
    if len(argv) == 1 or argv[1] in ("--help", "-help"):
        sys.stdout.write(top_help())
        return 0
    if argv[1] == "--version":
        sys.stdout.write(f"bedtools {VERSION}\n")
        return 0
    if argv[1] == "--contact":
        sys.stdout.write(contact_text())
        return 0
    if argv[1] == "--cram-ref":
        # Accepted as a general parameter; this reimplementation does not process CRAM.
        return 0
    cmd = argv[1]
    low = cmd.lower()
    cmd = ALIASES.get(low, low)
    if cmd not in COMMANDS:
        sys.stderr.write(f"error: unrecognized command: {argv[1]}\n")
        return 1
    try:
        return COMMANDS[cmd](argv[2:])
    except BrokenPipeError:
        return 0
    except Exception as exc:
        err(str(exc))
        return 1


if __name__ == "__main__":
    sys.exit(main(sys.argv))
