#!/usr/bin/env python3
"""A compact, original reimplementation of a BEDTools-like CLI.

This implementation is intentionally written from observed command-line
behaviour and supports the BED-oriented operations used by the bundled
examples: intersect, merge, complement, genomecov, jaccard, makewindows,
closest, subtract, flank, slop, coverage, map, window, sort, groupby and a
few small related utilities.  It does not shell out to bedtools or depend on
any project-specific packages.
"""

from __future__ import annotations

import bisect
import collections
import gzip
import math
import os
import random as pyrandom
import statistics
import sys
from typing import Dict, Iterable, List, Optional, Sequence, Tuple

VERSION = "b2e3657"
BIN_SIZE = 100000


# ---------------------------------------------------------------------------
# General formatting and IO helpers


def is_int(s: str) -> bool:
    try:
        int(s)
        return True
    except Exception:
        return False


def is_float(s: str) -> bool:
    try:
        float(s)
        return True
    except Exception:
        return False


def is_option_token(s: str) -> bool:
    if s in ("-", "stdin"):
        return False
    if not s.startswith("-"):
        return False
    # Negative numeric values are arguments, not option names.
    try:
        float(s)
        return False
    except Exception:
        return True


def split_fields(line: str) -> List[str]:
    line = line.rstrip("\n\r")
    if "\t" in line:
        return line.split("\t")
    return line.split()


def fmt_general(x) -> str:
    """C++-iostream-like compact numeric formatting used by many tools."""
    if isinstance(x, str):
        return x
    try:
        xf = float(x)
    except Exception:
        return str(x)
    if math.isnan(xf):
        return "nan"
    if math.isinf(xf):
        return "inf" if xf > 0 else "-inf"
    if abs(xf - round(xf)) < 1e-10:
        return str(int(round(xf)))
    return format(xf, ".6g")


def fmt_depth(x: float) -> str:
    if abs(x - round(x)) < 1e-10:
        return str(int(round(x)))
    return format(x, ".6g")


def out_line(fields: Sequence[object]) -> None:
    sys.stdout.write("\t".join(str(x) for x in fields) + "\n")


def err(msg: str) -> None:
    sys.stderr.write(msg)
    if not msg.endswith("\n"):
        sys.stderr.write("\n")


def open_text(path: str):
    if path in ("-", "stdin"):
        return sys.stdin
    if path.endswith(".gz"):
        return gzip.open(path, "rt")
    return open(path, "rt", newline=None)


class Record:
    __slots__ = (
        "fields",
        "chrom",
        "start",
        "end",
        "order",
        "line",
        "kind",
        "start_idx",
        "end_idx",
    )

    def __init__(self, fields: List[str], order: int = 0, line: str = ""):
        self.fields = fields
        self.order = order
        self.line = line
        self.chrom = fields[0] if fields else ""
        self.kind = "BED"
        self.start_idx = 1
        self.end_idx = 2
        if len(fields) >= 3 and is_int(fields[1]) and is_int(fields[2]):
            # BED-like, 0-based half-open.
            self.kind = "BED"
            self.start_idx = 1
            self.end_idx = 2
            self.start = int(fields[1])
            self.end = int(fields[2])
        elif len(fields) >= 5 and is_int(fields[3]) and is_int(fields[4]):
            # GFF/GTF-like, 1-based inclusive in the file.
            self.kind = "GFF"
            self.start_idx = 3
            self.end_idx = 4
            self.start = int(fields[3]) - 1
            self.end = int(fields[4])
        elif len(fields) >= 2 and is_int(fields[1]):
            # VCF-like: POS is 1-based; use REF length when available.
            self.kind = "VCF"
            self.start_idx = 1
            self.end_idx = -1
            self.start = int(fields[1]) - 1
            reflen = len(fields[3]) if len(fields) > 3 else 1
            self.end = self.start + max(1, reflen)
        else:
            raise ValueError("Could not parse interval fields")

    @property
    def strand(self) -> Optional[str]:
        return self.fields[5] if len(self.fields) >= 6 else None

    @property
    def name(self) -> str:
        if len(self.fields) >= 4:
            return self.fields[3]
        return f"{self.chrom}:{self.start}-{self.end}"

    def length(self) -> int:
        return max(0, self.end - self.start)

    def copy_fields(self) -> List[str]:
        return list(self.fields)

    def fields_with_coords(self, start: int, end: int) -> List[str]:
        f = list(self.fields)
        if self.kind == "BED":
            f[self.start_idx] = str(start)
            f[self.end_idx] = str(end)
        elif self.kind == "GFF":
            f[self.start_idx] = str(start + 1)
            f[self.end_idx] = str(end)
        elif self.kind == "VCF":
            f[self.start_idx] = str(start + 1)
        return f


def read_records(path: str) -> Tuple[List[str], List[Record]]:
    headers: List[str] = []
    recs: List[Record] = []
    close = False
    fh = open_text(path)
    close = fh is not sys.stdin
    try:
        for line in fh:
            stripped = line.rstrip("\n\r")
            if not stripped:
                continue
            if stripped.startswith("#") or stripped.startswith("track") or stripped.startswith("browser"):
                headers.append(stripped)
                continue
            fields = split_fields(stripped)
            if len(fields) < 3:
                # Match bedtools' tendency to complain about malformed interval files.
                raise ValueError(
                    f"It looks as though you have less than 3 columns in file {path}.  Are you sure your files are tab-delimited?"
                )
            try:
                recs.append(Record(fields, len(recs), stripped))
            except Exception as exc:
                raise ValueError(f"Error parsing interval in {path}: {stripped}") from exc
    finally:
        if close:
            fh.close()
    return headers, recs


def read_genome(path: str) -> List[Tuple[str, int]]:
    genome: List[Tuple[str, int]] = []
    close = False
    fh = open_text(path)
    close = fh is not sys.stdin
    try:
        for line in fh:
            line = line.strip()
            if not line or line.startswith("#"):
                continue
            f = split_fields(line)
            if len(f) >= 2 and is_int(f[1]):
                genome.append((f[0], int(f[1])))
    finally:
        if close:
            fh.close()
    return genome


class IntervalIndex:
    def __init__(self, records: Sequence[Record], bin_size: int = BIN_SIZE):
        self.records = list(records)
        self.bin_size = bin_size
        self.by_chrom: Dict[str, List[Record]] = collections.defaultdict(list)
        self.bins: Dict[str, Dict[int, List[Record]]] = collections.defaultdict(lambda: collections.defaultdict(list))
        self.sorted_by_chrom: Dict[str, List[Record]] = {}
        for r in self.records:
            self.by_chrom[r.chrom].append(r)
            if r.end > r.start:
                b0 = r.start // bin_size
                b1 = (r.end - 1) // bin_size
            else:
                b0 = b1 = r.start // bin_size
            for b in range(b0, b1 + 1):
                self.bins[r.chrom][b].append(r)
        for c, rs in self.by_chrom.items():
            self.sorted_by_chrom[c] = sorted(rs, key=lambda x: (x.start, x.end, x.order))

    def query(self, chrom: str, start: int, end: int) -> List[Record]:
        if end <= start:
            return []
        chrom_bins = self.bins.get(chrom)
        if not chrom_bins:
            return []
        b0 = start // self.bin_size
        b1 = (end - 1) // self.bin_size
        seen = set()
        out: List[Record] = []
        for b in range(b0, b1 + 1):
            for r in chrom_bins.get(b, []):
                ident = id(r)
                if ident in seen:
                    continue
                seen.add(ident)
                if r.end > start and r.start < end:
                    out.append(r)
        out.sort(key=lambda r: r.order)
        return out

    def all_chrom(self, chrom: str) -> List[Record]:
        return self.by_chrom.get(chrom, [])

    def sorted_chrom(self, chrom: str) -> List[Record]:
        return self.sorted_by_chrom.get(chrom, [])


# ---------------------------------------------------------------------------
# Interval utility functions


def overlap_len_coords(a0: int, a1: int, b0: int, b1: int) -> int:
    return max(0, min(a1, b1) - max(a0, b0))


def distance_between(a: Record, b: Record) -> int:
    if overlap_len_coords(a.start, a.end, b.start, b.end) > 0:
        return 0
    if b.end <= a.start:
        return a.start - b.end + 1
    return b.start - a.end + 1


def signed_distance(a: Record, b: Record, mode: str) -> int:
    d = distance_between(a, b)
    if d == 0:
        return 0
    # Reference orientation: lower coordinates are upstream (negative).
    sign = -1 if b.end <= a.start else 1
    if mode == "a" and a.strand == "-":
        sign *= -1
    elif mode == "b" and b.strand == "-":
        sign *= -1
    return sign * d


def strand_ok(a: Record, b: Record, same: bool = False, opp: bool = False) -> bool:
    if not same and not opp:
        return True
    sa, sb = a.strand, b.strand
    if sa not in ("+", "-") or sb not in ("+", "-"):
        return False
    return (sa == sb) if same else (sa != sb)


def record_segments(r: Record, split: bool = False) -> List[Tuple[int, int]]:
    if split and r.kind == "BED" and len(r.fields) >= 12 and is_int(r.fields[9]):
        try:
            sizes = [int(x) for x in r.fields[10].rstrip(",").split(",") if x != ""]
            starts = [int(x) for x in r.fields[11].rstrip(",").split(",") if x != ""]
            n = min(int(r.fields[9]), len(sizes), len(starts))
            segs = []
            for i in range(n):
                s = r.start + starts[i]
                e = s + sizes[i]
                if e > s:
                    segs.append((s, e))
            return segs or [(r.start, r.end)]
        except Exception:
            pass
    return [(r.start, r.end)]


def passes_fraction(olap: int, alen: int, blen: int, f: float, F: float, reciprocal: bool, either: bool) -> bool:
    if olap <= 0:
        return False
    alen = max(1, alen)
    blen = max(1, blen)
    af = olap / alen
    bf = olap / blen
    eps = 1e-12
    if reciprocal:
        return af + eps >= f and bf + eps >= f
    if either:
        return af + eps >= f or bf + eps >= F
    return af + eps >= f and bf + eps >= F


def overlap_pieces(
    a: Record,
    b: Record,
    f: float = 1e-9,
    F: float = 1e-9,
    reciprocal: bool = False,
    either: bool = False,
    split: bool = False,
) -> List[Tuple[int, int, int]]:
    pieces: List[Tuple[int, int, int]] = []
    for as0, as1 in record_segments(a, split):
        for bs0, bs1 in record_segments(b, split):
            s = max(as0, bs0)
            e = min(as1, bs1)
            ol = e - s
            if passes_fraction(ol, a.length(), b.length(), f, F, reciprocal, either):
                pieces.append((s, e, ol))
    return pieces


def null_b_fields(ncols: int) -> List[str]:
    if ncols <= 0:
        ncols = 3
    vals = []
    for i in range(ncols):
        if i == 0:
            vals.append(".")
        elif i in (1, 2):
            vals.append("-1")
        elif i == 4:
            vals.append("-1")
        else:
            vals.append(".")
    return vals


def max_field_count(files_records: Sequence[Sequence[Record]]) -> int:
    m = 3
    for rs in files_records:
        for r in rs:
            m = max(m, len(r.fields))
    return m


def merge_intervals(records: Sequence[Record], d: int = 0, same_strand: bool = False) -> List[Tuple[str, int, int, Optional[str], List[Record]]]:
    if same_strand:
        key = lambda r: (r.chrom, r.strand or "", r.start, r.end, r.order)
    else:
        key = lambda r: (r.chrom, r.start, r.end, r.order)
    rs = sorted(records, key=key)
    out: List[Tuple[str, int, int, Optional[str], List[Record]]] = []
    for r in rs:
        strand = r.strand if same_strand else None
        if not out or out[-1][0] != r.chrom or (same_strand and out[-1][3] != strand) or r.start > out[-1][2] + d:
            out.append((r.chrom, r.start, r.end, strand, [r]))
        else:
            chrom, s, e, st, members = out[-1]
            members.append(r)
            out[-1] = (chrom, s, max(e, r.end), st, members)
    if same_strand:
        out.sort(key=lambda x: (x[0], x[1], x[2], x[3] or ""))
    return out


def union_length(records: Sequence[Record]) -> int:
    return sum(e - s for _c, s, e, _st, _mem in merge_intervals(records))


def parse_cols(s: Optional[str]) -> List[int]:
    if not s:
        return []
    cols = []
    for part in s.split(","):
        part = part.strip()
        if part:
            cols.append(int(part))
    return cols


def parse_ops(s: Optional[str]) -> List[str]:
    if not s:
        return []
    return [x.strip() for x in s.split(",") if x.strip()]


def numeric_values(values: Sequence[str]) -> List[float]:
    nums = []
    for v in values:
        try:
            nums.append(float(v))
        except Exception:
            pass
    return nums


def aggregate_values(values: Sequence[str], op: str, delim: str = ",") -> str:
    vals = list(values)
    op = op.lower()
    nums = numeric_values(vals)
    if op in ("sum", "sum_distinct"):
        if op == "sum_distinct":
            nums = numeric_values(sorted(set(vals)))
        return fmt_general(sum(nums)) if nums else "0"
    if op in ("mean", "average"):
        return fmt_general(sum(nums) / len(nums)) if nums else "."
    if op == "median":
        return fmt_general(statistics.median(nums)) if nums else "."
    if op == "min":
        if nums and len(nums) == len(vals):
            return fmt_general(min(nums))
        return min(vals) if vals else "."
    if op == "max":
        if nums and len(nums) == len(vals):
            return fmt_general(max(nums))
        return max(vals) if vals else "."
    if op == "absmin":
        return fmt_general(min(nums, key=lambda x: abs(x))) if nums else "."
    if op == "absmax":
        return fmt_general(max(nums, key=lambda x: abs(x))) if nums else "."
    if op == "count":
        return str(len(vals))
    if op == "count_distinct":
        return str(len(set(vals)))
    if op == "collapse":
        return delim.join(vals)
    if op == "distinct":
        return delim.join(sorted(set(vals)))
    if op == "first":
        return vals[0] if vals else "."
    if op == "last":
        return vals[-1] if vals else "."
    if op in ("mode", "antimode"):
        if not vals:
            return "."
        counts = collections.Counter(vals)
        if op == "mode":
            best = max(counts.values())
        else:
            best = min(counts.values())
        choices = sorted(k for k, v in counts.items() if v == best)
        return choices[0]
    if op in ("stdev", "sstdev"):
        if not nums:
            return "."
        if op == "sstdev" and len(nums) > 1:
            return fmt_general(statistics.stdev(nums))
        if op == "stdev":
            return fmt_general(statistics.pstdev(nums))
        return "0"
    # Unknown op: behave like collapse, which is a forgiving fallback.
    return delim.join(vals) if vals else "."


def expand_col_op_pairs(cols: List[int], ops: List[str]) -> List[Tuple[int, str]]:
    if not cols:
        cols = [5]
    if not ops:
        ops = ["sum"]
    if len(cols) == len(ops):
        return list(zip(cols, ops))
    if len(cols) == 1:
        return [(cols[0], op) for op in ops]
    if len(ops) == 1:
        return [(col, ops[0]) for col in cols]
    n = min(len(cols), len(ops))
    return list(zip(cols[:n], ops[:n]))


def ensure_sorted(records: Sequence[Record], filename: str = "input") -> bool:
    prev: Optional[Record] = None
    for r in records:
        if prev is not None:
            if r.chrom < prev.chrom or (r.chrom == prev.chrom and r.start < prev.start):
                err(f"Error: Sorted input specified, but the file {filename} has the following out of order record")
                err("\t".join(r.fields))
                return False
        prev = r
    return True


# ---------------------------------------------------------------------------
# Help and top-level CLI


def top_help() -> str:
    return f"""bedtools is a powerful toolset for genome arithmetic.

Version:   {VERSION}
About:     developed in the quinlanlab.org and by many contributors worldwide.
Docs:      http://bedtools.readthedocs.io/
Code:      https://github.com/arq5x/bedtools2
Mail:      https://groups.google.com/forum/#!forum/bedtools-discuss

Usage:     bedtools <subcommand> [options]

The bedtools sub-commands include:

[ Genome arithmetic ]
    intersect     Find overlapping intervals in various ways.
    window        Find overlapping intervals within a window around an interval.
    closest       Find the closest, potentially non-overlapping interval.
    coverage      Compute the coverage over defined intervals.
    map           Apply a function to a column for each overlapping interval.
    genomecov     Compute the coverage over an entire genome.
    merge         Combine overlapping/nearby intervals into a single interval.
    cluster       Cluster (but don't merge) overlapping/nearby intervals.
    complement    Extract intervals _not_ represented by an interval file.
    shift         Adjust the position of intervals.
    subtract      Remove intervals based on overlaps b/w two files.
    slop          Adjust the size of intervals.
    flank         Create new intervals from the flanks of existing intervals.
    sort          Order the intervals in a file.
    random        Generate random intervals in a genome.
    shuffle       Randomly redistribute intervals in a genome.
    sample        Sample random records from file using reservoir sampling.
    spacing       Report the gap lengths between intervals in a file.
    annotate      Annotate coverage of features from multiple files.

[ Multi-way file comparisons ]
    multiinter    Identifies common intervals among multiple interval files.
    unionbedg     Combines coverage intervals from multiple BEDGRAPH files.

[ Paired-end manipulation ]
    pairtobed     Find pairs that overlap intervals in various ways.
    pairtopair    Find pairs that overlap other pairs in various ways.

[ Format conversion ]
    bamtobed      Convert BAM alignments to BED (& other) formats.
    bedtobam      Convert intervals to BAM records.
    bamtofastq    Convert BAM records to FASTQ records.
    bedpetobam    Convert BEDPE intervals to BAM records.
    bed12tobed6   Breaks BED12 intervals into discrete BED6 intervals.

[ Fasta manipulation ]
    getfasta      Use intervals to extract sequences from a FASTA file.
    maskfasta     Use intervals to mask sequences from a FASTA file.
    nuc           Profile the nucleotide content of intervals in a FASTA file.

[ BAM focused tools ]
    multicov      Counts coverage from multiple BAMs at specific intervals.
    tag           Tag BAM alignments based on overlaps with interval files.

[ Statistical relationships ]
    jaccard       Calculate the Jaccard statistic b/w two sets of intervals.
    reldist       Calculate the distribution of relative distances b/w two files.
    fisher        Calculate Fisher statistic b/w two feature files.

[ Miscellaneous tools ]
    overlap       Computes the amount of overlap from two intervals.
    igv           Create an IGV snapshot batch script.
    links         Create a HTML page of links to UCSC locations.
