def cmd_merge(args: List[str]) -> int:
    if "-h" in args or "--help" in args:
        sys.stderr.write(sub_help("merge"))
        return 1
    path = None
    d = 0
    same = False
    only_strand: Optional[str] = None
    cols: List[int] = []
    ops: List[str] = []
    delim = ","
    i = 0
    while i < len(args):
        t = args[i]
        if t == "-i":
            path = args[i + 1]
            i += 2
        elif t == "-d":
            d = int(float(args[i + 1]))
            i += 2
        elif t == "-s":
            same = True
            i += 1
        elif t == "-S":
            only_strand = args[i + 1]
            same = True
            i += 2
        elif t == "-c":
            cols = parse_cols(args[i + 1])
            i += 2
        elif t == "-o":
            ops = parse_ops(args[i + 1])
            i += 2
        elif t == "-delim":
            delim = args[i + 1]
            i += 2
        else:
            i += 1
    if path is None:
        return 0
    try:
        _h, records = read_records(path)
    except Exception as exc:
        err(str(exc))
        return 1
    if only_strand:
        records = [r for r in records if r.strand == only_strand]
    if not ensure_sorted(records, path):
        return 1
    pairs = expand_col_op_pairs(cols, ops) if cols or ops else []
    for chrom, s, e, st, members in merge_intervals(records, d=d, same_strand=same):
        row: List[str] = [chrom, str(s), str(e)]
        for col, op in pairs:
            vals = [m.fields[col - 1] for m in members if len(m.fields) >= col]
            row.append(aggregate_values(vals, op, delim))
        out_line(row)
    return 0


def cmd_complement(args: List[str]) -> int:
    if "-h" in args or "--help" in args:
        sys.stderr.write(sub_help("complement"))
        return 1
    ipath = gpath = None
    limit_to_input = False
    i = 0
    while i < len(args):
        if args[i] == "-i":
            ipath = args[i + 1]
            i += 2
        elif args[i] == "-g":
            gpath = args[i + 1]
            i += 2
        elif args[i] == "-L":
            limit_to_input = True
            i += 1
        else:
            i += 1
    if not ipath or not gpath:
        sys.stderr.write(sub_help("complement"))
        return 1
    try:
        _h, records = read_records(ipath)
        genome = read_genome(gpath)
    except Exception as exc:
        err(str(exc))
        return 1
    rec_by_chrom: Dict[str, List[Record]] = collections.defaultdict(list)
    for r in records:
        rec_by_chrom[r.chrom].append(r)
    for chrom, length in genome:
        if limit_to_input and chrom not in rec_by_chrom:
            continue
        merged = merge_intervals(rec_by_chrom.get(chrom, []))
        cur = 0
        for _c, s, e, _st, _m in merged:
            s = max(0, min(length, s))
            e = max(0, min(length, e))
            if s > cur:
                out_line([chrom, cur, s])
            cur = max(cur, e)
        if cur < length:
            out_line([chrom, cur, length])
    return 0


def cmd_jaccard(args: List[str]) -> int:
    if "-h" in args or "--help" in args:
        sys.stderr.write(sub_help("jaccard"))
        return 1
    a_path = b_path = None
    same = opp = False
    i = 0
    while i < len(args):
        t = args[i]
        if t == "-a":
            a_path = args[i + 1]
            i += 2
        elif t == "-b":
            b_path = args[i + 1]
            i += 2
        elif t == "-s":
            same = True
            i += 1
        elif t == "-S":
            opp = True
            i += 1
        elif t in ("-f", "-F", "-g"):
            i += 2
        elif t in ("-r", "-e", "-split", "-sorted", "-nonamecheck"):
            i += 1
        else:
            i += 1
    if not a_path or not b_path:
        sys.stderr.write(sub_help("jaccard"))
        return 1
    try:
        _h, arecs0 = read_records(a_path)
        _h, brecs0 = read_records(b_path)
    except Exception as exc:
        err(str(exc))
        return 1
    if same or opp:
        # Keep only pairable records; lengths are measured for records that can participate.
        astrands = {"+", "-"}
        arecs = [r for r in arecs0 if r.strand in astrands]
        brecs = [r for r in brecs0 if r.strand in astrands]
    else:
        arecs, brecs = arecs0, brecs0
    am = merge_intervals(arecs, same_strand=same)
    bm = merge_intervals(brecs, same_strand=same)
    a_len = sum(e - s for _c, s, e, _st, _m in am)
    b_len = sum(e - s for _c, s, e, _st, _m in bm)
    # Organize merged intervals by chromosome (and strand for -s).
    by_a: Dict[Tuple[str, Optional[str]], List[Tuple[int, int]]] = collections.defaultdict(list)
    by_b: Dict[Tuple[str, Optional[str]], List[Tuple[int, int]]] = collections.defaultdict(list)
    for c, s, e, st, _m in am:
        by_a[(c, st if same else None)].append((s, e))
    if same:
        for c, s, e, st, _m in bm:
            by_b[(c, st)].append((s, e))
    elif opp:
        # Opposite strand: compare + A to - B and vice versa without merging opposite strands together.
        am2 = merge_intervals(arecs, same_strand=True)
        bm2 = merge_intervals(brecs, same_strand=True)
        by_a.clear(); by_b.clear()
        a_len = sum(e - s for _c, s, e, _st, _m in am2)
        b_len = sum(e - s for _c, s, e, _st, _m in bm2)
        for c, s, e, st, _m in am2:
            by_a[(c, st)].append((s, e))
        for c, s, e, st, _m in bm2:
            by_b[(c, "+" if st == "-" else "-" if st == "+" else st)].append((s, e))
    else:
        for c, s, e, st, _m in bm:
            by_b[(c, None)].append((s, e))
    inter = 0
    n_inter = 0
    for key, av in by_a.items():
        bv = by_b.get(key, [])
        i = j = 0
        while i < len(av) and j < len(bv):
            s = max(av[i][0], bv[j][0])
            e = min(av[i][1], bv[j][1])
            if e > s:
                inter += e - s
                n_inter += 1
            if av[i][1] < bv[j][1]:
                i += 1
            else:
                j += 1
    union = a_len + b_len - inter
    jac = (inter / union) if union else 0.0
    out_line(["intersection", "union", "jaccard", "n_intersections"])
    out_line([inter, union, fmt_general(jac), n_inter])
    return 0


