# genomecov / coverage


def make_depth_events(records: Sequence[Record], chrom: str, length: int, strand: Optional[str] = None, split: bool = False) -> Dict[int, int]:
    events: Dict[int, int] = collections.defaultdict(int)
    for r in records:
        if r.chrom != chrom:
            continue
        if strand and r.strand != strand:
            continue
        for s, e in record_segments(r, split):
            s = max(0, min(length, s))
            e = max(0, min(length, e))
            if e <= s:
                continue
            events[s] += 1
            events[e] -= 1
    return events


def cmd_genomecov(args: List[str]) -> int:
    if "-h" in args or "--help" in args:
        sys.stderr.write(sub_help("genomecov"))
        return 1
    ipath = gpath = None
    bg = bga = dflag = dz = False
    strand = None
    max_depth: Optional[int] = None
    scale = 1.0
    split = False
    i = 0
    while i < len(args):
        t = args[i]
        if t == "-i":
            ipath = args[i + 1]
            i += 2
        elif t == "-ibam":
            err("BAM input is not supported by this reimplementation.")
            return 1
        elif t == "-g":
            gpath = args[i + 1]
            i += 2
        elif t == "-bg":
            bg = True
            i += 1
        elif t == "-bga":
            bga = True
            i += 1
        elif t == "-d":
            dflag = True
            i += 1
        elif t == "-dz":
            dz = True
            i += 1
        elif t == "-strand":
            strand = args[i + 1]
            i += 2
        elif t == "-max":
            max_depth = int(args[i + 1])
            i += 2
        elif t == "-scale":
            scale = float(args[i + 1])
            i += 2
        elif t == "-split":
            split = True
            i += 1
        else:
            i += 1
    if not ipath or not gpath:
        sys.stderr.write(sub_help("genomecov"))
        return 1
    try:
        _h, records = read_records(ipath)
        genome = read_genome(gpath)
    except Exception as exc:
        err(str(exc))
        return 1

    genome_hist: Dict[int, int] = collections.defaultdict(int)
    genome_size = 0
    for chrom, length in genome:
        genome_size += length
        events = make_depth_events(records, chrom, length, strand, split)
        positions = sorted(set([0, length]) | set(p for p in events if 0 <= p <= length))
        if dflag or dz:
            depth = 0
            ev_sorted = sorted(events.items())
            ev_i = 0
            for pos in range(0, length):
                while ev_i < len(ev_sorted) and ev_sorted[ev_i][0] == pos:
                    depth += ev_sorted[ev_i][1]
                    ev_i += 1
                val = depth * scale
                if dflag:
                    out_line([chrom, pos + 1, fmt_depth(val)])
                elif dz and depth != 0:
                    out_line([chrom, pos, fmt_depth(val)])
            continue
        if bg or bga:
            depth = 0
            prev = 0
            for p in sorted([x for x in set(events.keys()) if 0 <= x <= length] + [length]):
                if p > prev:
                    if bga or depth != 0:
                        if not bg or depth != 0:
                            out_line([chrom, prev, p, fmt_depth(depth * scale)])
                        elif bga:
                            out_line([chrom, prev, p, fmt_depth(depth * scale)])
                    elif bga:
                        out_line([chrom, prev, p, fmt_depth(depth * scale)])
                depth += events.get(p, 0)
                prev = p
            continue
        # Histogram mode.
        hist: Dict[int, int] = collections.defaultdict(int)
        depth = 0
        prev = 0
        for p in sorted([x for x in set(events.keys()) if 0 <= x <= length] + [length]):
            if p > prev:
                dep = depth
                if max_depth is not None and dep >= max_depth:
                    dep = max_depth
                hist[dep] += p - prev
            depth += events.get(p, 0)
            prev = p
        for dep in sorted(hist):
            count = hist[dep]
            if count == 0:
                continue
            genome_hist[dep] += count
            out_line([chrom, dep, count, length, fmt_general(count / length if length else 0)])
    if not (bg or bga or dflag or dz):
        for dep in sorted(genome_hist):
            count = genome_hist[dep]
            out_line(["genome", dep, count, genome_size, fmt_general(count / genome_size if genome_size else 0)])
    return 0


def coverage_for_a(a: Record, b_indexes: Sequence[IntervalIndex], opts) -> Tuple[int, List[Tuple[int, int]]]:
    count = 0
    segs: List[Tuple[int, int]] = []
    for idx in b_indexes:
        for b in idx.query(a.chrom, a.start, a.end):
            if not strand_ok(a, b, opts.get("s", False), opts.get("S", False)):
                continue
            pieces = overlap_pieces(a, b, opts.get("f", 1e-9), opts.get("F", 1e-9), opts.get("r", False), opts.get("e", False), opts.get("split", False))
            if pieces:
                count += 1
                for s, e, _ol in pieces:
                    s = max(s, a.start)
                    e = min(e, a.end)
                    if e > s:
                        segs.append((s, e))
    return count, segs


def coverage_depth_counts(a: Record, segs: Sequence[Tuple[int, int]]) -> Tuple[List[int], Dict[int, int], int]:
    length = a.length()
    events: Dict[int, int] = collections.defaultdict(int)
    for s, e in segs:
        events[max(0, s - a.start)] += 1
        events[min(length, e - a.start)] -= 1
    depths: List[int] = []
    hist: Dict[int, int] = collections.defaultdict(int)
    depth = 0
    ev = collections.defaultdict(int, events)
    for pos in range(length):
        depth += ev.get(pos, 0)
        depths.append(depth)
        hist[depth] += 1
    covered = sum(1 for x in depths if x > 0)
    return depths, hist, covered


def cmd_coverage(args: List[str]) -> int:
    if "-h" in args or "--help" in args:
        sys.stderr.write(sub_help("coverage"))
        return 1
    opts = {"a": None, "b": [], "counts": False, "d": False, "hist": False, "mean": False, "s": False, "S": False, "f": 1e-9, "F": 1e-9, "r": False, "e": False, "split": False, "header": False}
    i = 0
    while i < len(args):
        t = args[i]
        if t == "-a":
            opts["a"] = args[i + 1]; i += 2
        elif t == "-b":
            i += 1; bs = []
            while i < len(args) and not is_option_token(args[i]):
                bs.append(args[i]); i += 1
            opts["b"] = bs
        elif t in ("-counts", "-d", "-hist", "-mean", "-s", "-S", "-r", "-e", "-split", "-header"):
            opts[t.lstrip("-")] = True; i += 1
        elif t in ("-f", "-F"):
            opts[t.lstrip("-")] = float(args[i + 1]); i += 2
        else:
            i += 1
    if not opts["a"] or not opts["b"]:
        sys.stderr.write(sub_help("coverage")); return 1
    try:
        aheaders, arecs = read_records(str(opts["a"]))
        b_lists = [read_records(str(p))[1] for p in opts["b"]]
    except Exception as exc:
        err(str(exc)); return 1
    if opts["header"]:
        for h in aheaders: sys.stdout.write(h + "\n")
    b_indexes = [IntervalIndex(x) for x in b_lists]
    all_hist: Dict[int, int] = collections.defaultdict(int)
    all_len = 0
    for a in arecs:
        count, segs = coverage_for_a(a, b_indexes, opts)
        depths, hist, covered = coverage_depth_counts(a, segs)
        length = a.length()
        all_len += length
        for dep, cnt in hist.items(): all_hist[dep] += cnt
        if opts["d"]:
            for pos, dep in enumerate(depths, start=1):
                out_line(a.fields + [pos, dep])
        elif opts["hist"]:
            for dep in sorted(hist):
                cnt = hist[dep]
                out_line(a.fields + [dep, cnt, length, f"{(cnt / length if length else 0):.7f}"])
        elif opts["counts"]:
            out_line(a.fields + [count])
        elif opts["mean"]:
            mean = (sum(depths) / length) if length else 0.0
            out_line(a.fields + [f"{mean:.7f}"])
        else:
            out_line(a.fields + [count, covered, length, f"{(covered / length if length else 0):.7f}"])
    if opts["hist"]:
        for dep in sorted(all_hist):
            cnt = all_hist[dep]
            out_line(["all", dep, cnt, all_len, f"{(cnt / all_len if all_len else 0):.7f}"])
    return 0


