def parse_lr_b(args: List[str]) -> Tuple[float, float, bool]:
    l = r = 0.0
    pct = False
    i = 0
    while i < len(args):
        if args[i] == "-b":
            l = r = float(args[i+1]); i += 2
        elif args[i] == "-l":
            l = float(args[i+1]); i += 2
        elif args[i] == "-r":
            r = float(args[i+1]); i += 2
        elif args[i] == "-pct":
            pct = True; i += 1
        else:
            i += 1
    return l, r, pct


def cmd_slop(args: List[str]) -> int:
    if "-h" in args or "--help" in args:
        sys.stderr.write(sub_help("slop")); return 1
    ipath = gpath = None; strand = False
    i = 0
    while i < len(args):
        if args[i] == "-i": ipath = args[i+1]; i += 2
        elif args[i] == "-g": gpath = args[i+1]; i += 2
        elif args[i] == "-s": strand = True; i += 1
        else: i += 1
    l, r, pct = parse_lr_b(args)
    if not ipath or not gpath:
        sys.stderr.write(sub_help("slop")); return 1
    try:
        _h, recs = read_records(ipath); genome = dict(read_genome(gpath))
    except Exception as exc:
        err(str(exc)); return 1
    for rec in recs:
        left, right = l, r
        if pct:
            left = int(rec.length() * left); right = int(rec.length() * right)
        else:
            left = int(left); right = int(right)
        if strand and rec.strand == "-":
            left, right = right, left
        s = max(0, rec.start - int(left))
        e = rec.end + int(right)
        if rec.chrom in genome: e = min(genome[rec.chrom], e)
        if e < s: e = s
        out_line(rec.fields_with_coords(s, e))
    return 0


