def cmd_makewindows(args: List[str]) -> int:
    if "-h" in args or "--help" in args:
        sys.stderr.write(sub_help("makewindows")); return 1
    gpath = bpath = None; w = step = n = None; name_mode = None; reverse = False
    i = 0
    while i < len(args):
        t = args[i]
        if t == "-g": gpath = args[i+1]; i += 2
        elif t == "-b": bpath = args[i+1]; i += 2
        elif t == "-w": w = int(args[i+1]); i += 2
        elif t == "-s": step = int(args[i+1]); i += 2
        elif t == "-n": n = int(args[i+1]); i += 2
        elif t == "-i": name_mode = args[i+1]; i += 2
        elif t == "-reverse": reverse = True; i += 1
        else: i += 1
    intervals: List[Tuple[str, int, int, str]] = []
    try:
        if gpath:
            for c, ln in read_genome(gpath): intervals.append((c, 0, ln, c))
        elif bpath:
            _h, recs = read_records(bpath)
            for r in recs: intervals.append((r.chrom, r.start, r.end, r.name))
        else:
            sys.stderr.write(sub_help("makewindows")); return 1
    except Exception as exc:
        err(str(exc)); return 1
    for chrom, start, end, src in intervals:
        length = end - start
        wins: List[Tuple[int, int]] = []
        if n is not None:
            if length < n or n <= 0:
                err(f"WARNING: Interval {chrom}:{start}-{end} is smaller than the number of windows requested. Skipping.")
                continue
            base = length // n
            if base <= 0:
                continue
            for k in range(n):
                s = start + k * base
                e = start + (k + 1) * base if k < n - 1 else end
                if e > s: wins.append((s, e))
        else:
            if not w or w <= 0:
                continue
            stp = step or w
            pos = start
            while pos < end:
                wins.append((pos, min(end, pos + w)))
                pos += stp
        total = len(wins)
        for idx, (s, e) in enumerate(wins, start=1):
            row: List[object] = [chrom, s, e]
            num = total - idx + 1 if reverse else idx
            if name_mode == "winnum": row.append(num)
            elif name_mode == "src": row.append(src)
            elif name_mode == "srcwinnum": row.append(f"{src}_{num}")
            out_line(row)
    return 0


def cmd_sort(args: List[str]) -> int:
    if "-h" in args or "--help" in args:
        sys.stderr.write(sub_help("sort")); return 1
    ipath = None; gpath = None; mode = "pos"
    i = 0
    while i < len(args):
        t = args[i]
        if t == "-i": ipath = args[i+1]; i += 2
        elif t in ("-g", "-faidx"):
            gpath = args[i+1]; i += 2
        elif t in ("-sizeA", "-sizeD", "-chrThenSizeA", "-chrThenSizeD", "-chrThenScoreA", "-chrThenScoreD"):
            mode = t; i += 1
        else: i += 1
    if not ipath:
        sys.stderr.write(sub_help("sort")); return 1
    try:
        _h, recs = read_records(ipath)
    except Exception as exc:
        err(str(exc)); return 1
    order = None
    if gpath:
        order = {c: i for i, (c, _l) in enumerate(read_genome(gpath))}
    def chrom_key(r):
        return order.get(r.chrom, len(order) + 1) if order else r.chrom
    if mode == "-sizeA":
        key = lambda r: (r.length(), chrom_key(r), r.start)
    elif mode == "-sizeD":
        key = lambda r: (-r.length(), chrom_key(r), r.start)
    elif mode == "-chrThenSizeA":
        key = lambda r: (chrom_key(r), r.length(), r.start)
    elif mode == "-chrThenSizeD":
        key = lambda r: (chrom_key(r), -r.length(), r.start)
    elif mode == "-chrThenScoreA":
        key = lambda r: (chrom_key(r), float(r.fields[4]) if len(r.fields) > 4 and is_float(r.fields[4]) else 0, r.start)
    elif mode == "-chrThenScoreD":
        key = lambda r: (chrom_key(r), -(float(r.fields[4]) if len(r.fields) > 4 and is_float(r.fields[4]) else 0), r.start)
    else:
        key = lambda r: (chrom_key(r), r.start, r.end)
    for r in sorted(recs, key=key):
        out_line(r.fields)
    return 0


def cmd_groupby(args: List[str]) -> int:
    if "-h" in args or "--help" in args:
        sys.stderr.write(sub_help("groupby")); return 1
    ipath = None; gcols = [1, 2, 3]; cols: List[int] = []; ops: List[str] = []; delim = ","; header = False
    i = 0
    while i < len(args):
        t = args[i]
        if t == "-i": ipath = args[i+1]; i += 2
        elif t in ("-g", "-grp"):
            gcols = parse_cols(args[i+1]); i += 2
        elif t == "-c": cols = parse_cols(args[i+1]); i += 2
        elif t == "-o": ops = parse_ops(args[i+1]); i += 2
        elif t == "-delim": delim = args[i+1]; i += 2
        elif t == "-header": header = True; i += 1
        else: i += 1
    if not ipath:
        ipath = "-"
    try:
        h, recs = read_records(ipath)
    except Exception:
        # groupby is general tabular, not necessarily intervals. Re-read simply.
        lines=[]; headers=[]
        fh=open_text(ipath)
        close=fh is not sys.stdin
        try:
            for line in fh:
                line=line.rstrip("\n\r")
                if not line: continue
                if line.startswith("#"):
                    headers.append(line); continue
                lines.append(split_fields(line))
        finally:
            if close: fh.close()
        if header:
            for x in headers: sys.stdout.write(x+"\n")
        return groupby_fields(lines, gcols, cols, ops, delim)
    lines = [r.fields for r in recs]
    if header:
        for x in h: sys.stdout.write(x+"\n")
    return groupby_fields(lines, gcols, cols, ops, delim)


def groupby_fields(lines: List[List[str]], gcols: List[int], cols: List[int], ops: List[str], delim: str) -> int:
    pairs = expand_col_op_pairs(cols, ops)
    cur_key = None; group: List[List[str]] = []
    def flush():
        if not group: return
        key_fields = [group[0][c-1] for c in gcols if len(group[0]) >= c]
        row = list(key_fields)
        for col, op in pairs:
            vals = [ln[col-1] for ln in group if len(ln) >= col]
            row.append(aggregate_values(vals, op, delim))
        out_line(row)
    for f in lines:
        key = tuple(f[c-1] if len(f) >= c else "" for c in gcols)
        if cur_key is None:
            cur_key = key; group = [f]
        elif key == cur_key:
            group.append(f)
        else:
            flush(); cur_key = key; group = [f]
    flush()
    return 0


def cmd_cluster(args: List[str]) -> int:
    ipath = None; d = 0; same = False; only = None
    i=0
    while i < len(args):
        if args[i] == "-i": ipath=args[i+1]; i+=2
        elif args[i] == "-d": d=int(args[i+1]); i+=2
        elif args[i] == "-s": same=True; i+=1
        elif args[i] == "-S": same=True; only=args[i+1]; i+=2
        elif args[i] in ("-h", "--help"):
            sys.stderr.write(sub_help("cluster")); return 1
        else: i+=1
    if not ipath: return 0
    try: _h,recs=read_records(ipath)
    except Exception as exc: err(str(exc)); return 1
    if only: recs=[r for r in recs if r.strand==only]
    work = sorted(recs, key=lambda r: (r.chrom, r.strand or "", r.start, r.end)) if same else recs
    cid=0; cur_chrom=None; cur_end=-1; cur_strand=None
    for r in work:
        st = r.strand if same else None
        if cur_chrom != r.chrom or (same and cur_strand != st) or r.start > cur_end + d:
            cid += 1; cur_chrom = r.chrom; cur_end = r.end; cur_strand = st
        else:
            cur_end = max(cur_end, r.end)
        out_line(r.fields + [cid])
    return 0


def cmd_spacing(args: List[str]) -> int:
    ipath=None
    i=0
    while i<len(args):
        if args[i]=="-i": ipath=args[i+1]; i+=2
        elif args[i] in ("-h","--help"):
